return ['domain'=>'zinn-chat','plural-forms'=>'nplurals=2; plural=(n != 1);','language'=>'mr','project-id-version'=>'zinn-chat','pot-creation-date'=>'2026-10-02T00:01:12+00:00','po-revision-date'=>'2026-10-02T00:01:12+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Zinn® Chat'=>'Zinn® Chat','https://zinndigital.com/wordpress-plugins/zinn-chat'=>'https://zinndigital.com/wordpress-plugins/zinn-chat','A complete help desk and AI assistant that runs on your own WordPress: an AI that answers from your own pages with links, live chat, and support tickets in wp-admin, on a submit-a-ticket page and in the WooCommerce account area. Under 10 KB on the page and no requests at all until a visitor opens it.'=>'आपल्या स्वतःच्या WordPress वर चालणारे एक संपूर्ण हेल्प डेस्क आणि AI असिस्टंट: एक AI जो तुमच्या स्वतःच्या पानांवरून लिंक्ससह उत्तरे देतो, लाईव्ह चॅट आणि wp-admin मधील सपोर्ट तिकीट्स, तिकीट सबमिट करण्याचे पान आणि WooCommerce अकाउंट एरियामध्ये उपलब्ध असतो. पानावर १० केबी पेक्षा कमी साईझ आणि जोपर्यंत एखादा व्हिजिटर ते उघडत नाही तोपर्यंत एकही विनंती नाही.','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','Inbox'=>'इनबॉक्स','Tickets'=>'तिकिटे','Assistant'=>'सहाय्यक','Settings'=>'सेटिंग्ज','Setup'=>'सेटअप','Zinn® Chat could not create its database tables:'=>'Zinn® Chat त्याचे डेटाबेस टेबल तयार करू शकले नाही:','The AI assistant could not answer a visitor:'=>'एआय असिस्टंट एका अभ्यागताच्या प्रश्नाचे उत्तर देऊ शकला नाही:','Fix it'=>'हे दुरुस्त करा','Loading…'=>'लोड होत आहे…','This screen needs JavaScript.'=>'या स्क्रीनसाठी जावास्क्रिप्ट आवश्यक आहे.','Chat'=>'चॅट','AI assistant'=>'AI सहाय्यक','Tickets and email'=>'तिकिटे आणि ईमेल','Site index'=>'साइट इंडेक्स','Privacy and spam'=>'गोपनीयता आणि स्पॅम','Connect to Zinn Digital®'=>'Zinn Digital® शी कनेक्ट करा','AI agents (MCP)'=>'AI एजंट्स (MCP)','Show the chat on the site'=>'साइटवर चॅट दाखवा','Nothing appears on the site, and nothing is loaded, until this is ticked.'=>'येथे खूण करेपर्यंत साइटवर काहीही दिसत नाही आणि काहीही लोड होत नाही.','Chat title'=>'चॅट शीर्षक','Greeting'=>'अभिवादन','The first thing a visitor sees.'=>'भेटणाऱ्या व्यक्तीला दिसणारी पहिली गोष्ट.','Greeting when nobody can answer'=>'जेव्हा कोणीही उत्तर देऊ शकत नाही तेव्हाचे अभिवादन','Colour'=>'रंग','Text colour on the colour'=>'रंगावरील मजकुराचा रंग','Position'=>'स्थिती','Bottom, end side (right in left-to-right languages)'=>'तळाशी, शेवटची बाजू (डावीकडून-उजव्या भाषांमध्ये उजवीकडे)','Bottom, start side'=>'तळाची, सुरुवातीची बाजू','Offer "Talk to a person"'=>'"एका व्यक्तीशी बोला" ही ऑफर द्या','Shown while somebody has the Inbox open and is not set to away.'=>'जेव्हा कोणीतरी इनबॉक्स उघडून ठेवले आहे आणि अनुपलब्ध (away) म्हणून सेट केलेले नाही तेव्हा हे दाखवले जाते.','Hide the chat from your support team while they are signed in'=>'तुमच्या सपोर्ट टीमने लॉग इन केलेले असताना त्यांच्यापासून चॅट लपवा','Show "Powered by Zinn® Chat" under the chat'=>'चॅटखाली "Powered by Zinn® Chat" दाखवा','Optional. Off unless you turn it on.'=>'पर्यायी. तुम्ही सुरू केल्याशिवाय बंद राहील.','Let the AI assistant answer visitors'=>'एआय असिस्टंटला अभ्यागतांची उत्तरे देऊ द्या','Assistant name'=>'सहाय्यकाचे नाव','Extra instructions for the assistant'=>'सहायकासाठी अतिरिक्त सूचना','For example: "Always mention our 30-day returns." They cannot override the safety rules.'=>'उदाहरणार्थ: "आमच्या ३० दिवसांच्या परताव्याचा नेहमी उल्लेख करा." ते सुरक्षेच्या नियमांचे उल्लंघन करू शकत नाहीत.','Answer language'=>'उत्तर भाषा','"auto" answers in the visitor\'s own language; or a locale such as en_GB or de_DE to always answer in one language.'=>'"auto" अभ्यागतच्या स्वतःच्या भाषेत उत्तरे देतो; किंवा एकाच भाषेत नेहमी उत्तर देण्यासाठी en_GB किंवा de_DE सारखे लोकेल.','Minimum relevance'=>'किमान सुसंगतता','Passages scoring below this (0 to 0.95) are not used, and the assistant says it does not know. Check scores in the test console.'=>'यापेक्षा कमी गुण मिळणारे (० ते 0.95) उतारे वापरले जात नाहीत, आणि सहाय्यक (assistant) माहीत नसल्याचे सांगतो. चाचणी कन्सोलमध्ये गुण तपासा.','Offer a person after this many unanswered questions'=>'इतके अनुत्तरित प्रश्न विचारल्यानंतर एखाद्या व्यक्तीला ऑफर द्या','Longest answer (tokens)'=>'सर्वात लांब उत्तर (टोकेन)','Accept support tickets'=>'सपोर्ट तिकीट स्वीकारा','Support page'=>'सपोर्ट पेज','The page with the [zinn_chat_support] shortcode or the Support page block. Ticket links in emails open this page.'=>'[zinn_chat_support] शॉर्टकोड किंवा सपोर्ट पेज ब्लॉक असलेले पेज. ई-मेलमधील तिकीट लिंक्स हे पेज उघडतात.','Send team alerts to'=>'टीम अलर्ट पाठवा','One or more email addresses, separated by commas. Empty: the site admin email.'=>'एक किंवा अधिक ई-मेल पत्ते, स्वल्पविरामाने विभक्त केलेले. रिकामे: साइट प्रशासक ई-मेल.','Sender name on emails'=>'ईमेल्सवरील प्रेषकाचे नाव','Email the team when a visitor waits for a person longer than (minutes)'=>'एखादा आगंतुक एखाद्या व्यक्तीची (मिनीट्स) पेक्षा जास्त वेळ प्रतीक्षा करत असल्यास टीमला ईमेल पाठवा','Private ticket links work for (days after the last message)'=>'खाजगी तिकीट लिंक्स यासाठी काम करतात (शेवटच्या संदेशानंतरचे दिवस)','After that the page offers to email a new link.'=>'त्यानंतर पेज नवीन दुवा ईमेल करण्याची ऑफर देते.','Add a Support tab to the WooCommerce account area'=>'WooCommerce खात्याच्या क्षेत्रात सपोर्ट टॅब जोडा','Let the assistant tell signed-in customers about their own orders'=>'साइन-इन केलेल्या ग्राहकांना त्यांच्या स्वतःच्या ऑर्डर्सबद्दल सहाय्यकाला सांगू द्या','Answers "where is my order?" from the order status and tracking.'=>'ऑर्डर स्थिती आणि ट्रॅकिंगवरून "माझी ऑर्डर कुठे आहे?" या प्रश्नांची उत्तरे मिळतात.','Content the assistant reads'=>'सहाय्यक वाचत असलेली सामग्री','None ticked means every public type.'=>'कोणतीही निवड न केल्यास सर्व सार्वजनिक प्रकार लागू होतात.','WooCommerce products, prices, stock, shipping and payment methods'=>'WooCommerce उत्पादने, किंमती, स्टॉक, शिपिंग आणि पेमेंट पद्धती','Forums (bbPress, BuddyBoss, wpForo)'=>'फोरम्स (bbPress, BuddyBoss, wpForo)','Read pages as visitors see them when a page builder\'s content cannot be read directly'=>'जेव्हा पेज बिल्डरची सामग्री थेट वाचता येत नाही, तेव्हा पेज बघा जसे अभ्यागत ते पाहतात','Fetches the page from your own site in the background.'=>'तुमच्या स्वतःच्या साइटवरून पार्श्वभूमीत पृष्ठ आणते.','Never read these posts or pages (IDs)'=>'कधीही या पोस्ट किंवा पृष्ठे (ID) वाचू नका','Comma-separated.'=>'स्वल्पविरामाने विभक्त केलेले.','Ask visitors to agree before a chat or ticket'=>'चॅट किंवा तिकीट सुरू करण्यापूर्वी अभ्यागतांना सहमती देण्यास सांगा','Agreement text'=>'करार मजकूर','Privacy policy link'=>'गोपनीयता धोरण दुवा','Empty: the site\'s privacy policy page.'=>'रिकामे: साइटचे गोपनीयता धोरण पृष्ठ.','Delete finished chats and tickets after (days)'=>'पूर्ण झालेले चॅट्स आणि तिकीट्स (दिवसांनंतर) हटवा','0 keeps them.'=>'0 त्यांना ठेवते.','Store visitors\' IP addresses'=>'अभ्यागतांचे आयपी पत्ते संचयित करा','Off: only a coded form is kept, enough for spam limits.'=>'बंद: फक्त एक कोड केलेले स्वरूप ठेवले जाते, स्पॅम मर्यादेसाठी पुरेसे.','Messages per visitor per hour'=>'प्रत्येक अभ्यागत प्रति तास संदेश','Chats per visitor per day'=>'प्रत्येक अभ्यागत प्रति दिवस चॅट्स','Tickets per visitor per day'=>'प्रति आगंतुक प्रति दिन तिकिटे','Longest chat message (characters)'=>'सर्वात लांब चॅट संदेश (अक्षरे)','Block list'=>'ब्लॉक यादी','One per line: an IP address, an email address, @domain.com, or a word.'=>'एका ओळीत एक: आयपी (IP) पत्ता, ईमेल पत्ता, @domain.com किंवा एक शब्द.','Where chats are answered'=>'चॅट्सची उत्तरे कुठे दिली जातात','"This site" keeps everything in this site\'s database and uses your own AI key. "Zinn Digital®" uses the hosted inbox in the Zinn® app (for Zinn® hosting customers).'=>'"ही साइट" या साइटच्या डेटाबेसमध्ये सर्वकाही ठेवते आणि तुमची स्वतःची AI की वापरते. "Zinn Digital®" हे Zinn® ॲपमधील होस्ट केलेले इनबॉक्स वापरते (Zinn® होस्टिंग ग्राहकांसाठी).','This site (recommended)'=>'हे साइट (शिफारस केलेले)','Zinn Digital® app'=>'Zinn Digital® ॲप','Zinn® widget key'=>'Zinn® विजेट की','From the Zinn® app: Live chat, then your widget. Starts with zc_.'=>'Zinn® अॅपवरून: थेट चॅट, नंतर तुमचे विजेट. zc_ सह सुरू होते.','Allow AI agents (MCP)'=>'AI एजंटना परवानगी द्या (MCP)','Off: the tools below and their REST routes are not registered at all.'=>'बंद: खालील साधने आणि त्यांचे REST रूट्स अजिबात नोंदणीकृत नाहीत.','Zinn® Chat settings'=>'Zinn® Chat सेटिंग्ज','Settings saved.'=>'सेटिंग्ज सेव्ह केल्या आहेत.','The assistant uses your own AI key.'=>'सहायक तुमच्या स्वतःच्या AI की चा वापर करतो.','AI providers and models'=>'AI प्रदाते आणि मॉडेल्स','— None —'=>'— काहीही नाही —','Saved — leave empty to keep'=>'जतन केले — तसेच ठेवण्यासाठी रिकामे सोडा','Remove the saved key'=>'जतन केलेली की काढा','You are not allowed to change these settings.'=>'तुम्हाला हे सेटिंग्ज बदलण्याची परवानगी नाही.','Turn the chat on'=>'चॅट चालू करा','The chat is showing on your site.'=>'चॅट तुमच्या साइटवर दिसत आहे.','Nothing is shown or loaded on your site until you turn it on.'=>'तुम्ही चालू करेपर्यंत तुमच्या साइटवर काहीही दर्शवले किंवा लोड केले जात नाही.','Turn off'=>'बंद करा','Turn on'=>'चालू करा','Connect your AI provider'=>'तुमचा एआय प्रोव्हायडर जोडा','Connected. Site search uses %1$s (%2$s).'=>'कनेक्ट केले आहे. साइट शोध %1$s (%2$s) वापरतो.','Connected. Your provider cannot build a meaning-based index, so the assistant uses keyword search. Add a Google Gemini, OpenAI, Mistral or OpenRouter key for better answers.'=>'कनेक्टेड आहे. तुमचा प्रोव्हायडर अर्थ-आधारित इंडेक्स तयार करू शकत नाही, त्यामुळे सहाय्यक कीवर्ड शोध वापरतो. अधिक चांगल्या उत्तरांसाठी Google Gemini, OpenAI, Mistral किंवा OpenRouter की जोडा.','Add a key for Google Gemini, OpenAI, Anthropic Claude, Mistral, OpenRouter or any OpenAI-compatible service. The newest model is chosen for you; you can change it.'=>'Google Gemini, OpenAI, Anthropic Claude, Mistral, OpenRouter किंवा कोणत्याही OpenAI-सुसंगत सेवेसाठी की जोडा. नवीन मॉडेल तुमच्यासाठी निवडले आहे; तुम्ही ते बदलू शकता.','AI providers'=>'एआय प्रदाते','Let the assistant read your site'=>'सहाय्यकाला तुमची साइट वाचू द्या','%1$d pages read, %2$d waiting, %3$d passages. New and edited content is picked up automatically.'=>'%1$d पृष्ठे वाचली, %2$d प्रतीक्षेत आहेत, %3$d परिच्छेद. नवीन आणि संपादित सामग्री आपोआप घेतली जाते.','Read the whole site now'=>'आता संपूर्ण साइट वाचा','Create your support page'=>'तुमचे सपोर्ट पेज तयार करा','Visitors submit tickets there, and ticket emails link to it.'=>'अभ्यागत तिथे तिकीट सबमिट करतात आणि तिकिटाचे ईमेल त्यावर लिंक करतात.','A page with the ticket form, where customers also follow their requests.'=>'तिकीट फॉर्म असलेले पेज, जिथे ग्राहक त्यांच्या विनंत्यांचा मागोवा सुद्धा घेतात.','View'=>'पाहा','Create the support page'=>'समर्थन पृष्ठ तयार करा','Add "Submit a ticket" and "Chat with us" to a menu'=>'मेनूमध्ये "तिकीट सबमिट करा" आणि "आमच्याशी चॅट करा" जोडा','Appearance, Menus: use the Zinn® Chat box. Or add the Zinn® Chat blocks to any page, in any page builder.'=>'स्वरूप, मेनू: Zinn® Chat बॉक्स वापरा. किंवा कोणत्याही पेज बिल्डरमध्ये कोणत्याही पेजवर Zinn® Chat ब्लॉक जोडा.','Menus'=>'मेनू','WooCommerce account area'=>'WooCommerce खाते क्षेत्र','Customers see their tickets under Support in My Account, and the assistant can tell them where their order is.'=>'ग्राहक त्यांची तिकिटे \'माय अकाउंट\' मधील \'सपोर्ट\' अंतर्गत पाहू शकतात आणि असिस्टंट त्यांना त्यांची ऑर्डर कुठे आहे हे सांगू शकतो.','Test the assistant'=>'सहायक तपासा','Ask it questions and see exactly which pages it answered from, including out-of-date ones.'=>'त्याला प्रश्न विचारून ते जुन्या पृष्ठांसह नेमक्या कोणत्या पृष्ठांवरून उत्तर दिले गेले हे तपासा.','Open the test console'=>'चाचणी कन्सोल उघडा','Answer live chats'=>'थेट चॅटला उत्तर द्या','Visitors can ask for a person while you have the Inbox open. It works on a phone too.'=>'इनबॉक्स उघडे असताना भेट देणारे व्यक्तीबद्दल विचारू शकतात. हे फोनवरही काम करते.','Open the Inbox'=>'इनबॉक्स उघडा','Set up Zinn® Chat'=>'Zinn® Chat सेटअप करा','This site is connected to the Zinn Digital® app: chats are answered there. To run the help desk on this site instead, choose "This site" under Settings, Connect to Zinn Digital®.'=>'हे साइट Zinn Digital® ॲपशी कनेक्ट केलेले आहे: चॅट्सचे उत्तर तिथे दिले जाते. याऐवजी या साइटवर हेल्प डेस्क चालवण्यासाठी, सेटिंग्ज अंतर्गत "This site" निवडा, Zinn Digital® शी कनेक्ट करा.','You are not allowed to do that.'=>'तुम्हाला असे करण्याची परवानगी नाही.','Unlimited agents, with a Support agent role that sees only chats and tickets'=>'अमर्यादित एजंट्स, सपोर्ट एजंट भूमिकेसह जे फक्त चॅट्स आणि तिकीट्स पाहतात','Reply to tickets by email'=>'ईमेलद्वारे तिकिटांना उत्तर द्या','Knowledge base: articles, categories, search, and a KB section in the chat'=>'ज्ञान आधार: लेख, श्रेणी, शोध आणि चॅटमधील केबी विभाग','Saved replies, business hours, priorities and SLAs'=>'जतन केलेली उत्तरे, व्यवसायाची वेळ, प्राधान्यक्रम आणि SLA','Suggested replies, thread summaries and auto-tagging by AI'=>'AI द्वारे सुचवलेली उत्तरे, थ्रेड सारांश आणि स्वयंचलित टॅगिंग','Knowledge-gap report: the questions your site could not answer'=>'ज्ञान-फाट्याची अहवाल: तुमच्या साईटने ज्या प्रश्नांची उत्तरे दिली नाहीत','Push notifications and an installable agent app for your phone'=>'पुश सूचना आणि तुमच्या फोनसाठी इंस्टॉल करण्यायोग्य एजंट ॲप','Proactive messages, reports, webhooks, Slack and Telegram alerts'=>'सक्रिय संदेश, अहवाल, वेबहूक, Slack आणि Telegram अलर्ट्स','Zinn® Chat Pro'=>'Zinn® Chat Pro','From $%1$d a month or $%2$d a year for one site.'=>'एक साइटसाठी दरमहा $%1$d किंवा दरवर्षी $%2$d पासून पुढे.','Try Pro free for 14 days'=>'प्रो (Pro) ची १४ दिवसांसाठी विनामूल्य चाचणी करा','See plans'=>'प्लॅन पहा','No card needed for the trial.'=>'चाचणीसाठी कार्डची आवश्यकता नाही.','The makers of ChatGPT. A good all-rounder.'=>'ChatGPT चे निर्माते. एक चांगला सर्वसमावेशक पर्याय.','The makers of Claude. Strong at writing and careful reasoning.'=>'Claude चे निर्माते. लेखन आणि काळजीपूर्वक युक्तिवादात पटाईत.','Google\'s Gemini models. Fast and inexpensive.'=>'Google चे Gemini मॉडेल. जलद आणि स्वस्त.','A European AI company with fast, inexpensive models.'=>'जलद आणि स्वस्त मॉडेल्स असलेली युरोपियन एआय कंपनी.','Low-cost models that are good at writing and code.'=>'लेखन आणि कोडिंगसाठी उत्तम असलेले कमी किमतीचे मॉडेल्स.','One key for models from many different providers.'=>'अनेक वेगवेगळ्या प्रदात्यांच्या मॉडेल्ससाठी एकच की.','Any service that works like OpenAI\'s API, including a model running on your own computer or server.'=>'OpenAI च्या API प्रमाणे कार्य करणारी कोणतीही सेवा, ज्यामध्ये तुमच्या स्वतःच्या संगणकावर किंवा सर्व्हरवर चालणारे मॉडेल देखील समाविष्ट आहे.','General (used when nothing more specific is set)'=>'सर्वसाधारण (जेव्हा इतर कोणतेही विशिष्ट प्राधान्य सेट केलेले नसते तेव्हा वापरले जाते)','Writing and rewriting'=>'लिहित आहे आणि पुन्हा लिहित आहे','Translation'=>'भाषांतर','Code and CSS'=>'कोड आणि सीएसएस','Sorry, you are not allowed to access this page.'=>'क्षमस्व, तुम्हाला या पृष्ठावर प्रवेश करण्याची परवानगी नाही.','These settings are shared by every plugin that uses them: %s.'=>'ही सेटिंग्ज त्यांचा वापर करणाऱ्या प्रत्येक प्लगइनद्वारे सामायिक केली जातात: %s.','Your keys are encrypted in this site\'s database and are only ever sent to the provider you chose — never to us.'=>'तुमच्या साइटच्या डेटाबेसमध्ये तुमच्या की एन्क्रिप्ट केल्या जातात आणि त्या फक्त तुम्ही निवडलेल्या प्रदात्याकडे पाठवल्या जातात—आमच्याकडे कधीही नाही.','Step 1 of 2: choose an AI provider'=>'पायरी १ पैकी २: AI प्रदाता निवडा','You bring your own key, so you pay the provider directly for what you use. Not sure? Any of these works well; you can add more later.'=>'तुम्ही तुमची स्वतःची की आणता, त्यामुळे तुम्ही जे वापरता त्यासाठी थेट प्रदात्याला पैसे देता. खात्री नाही? यापैकी कोणतीही एक चांगली काम करते; तुम्ही नंतर आणखी जोडू शकता.','Next'=>'पुढील','Step 2 of 2: connect %s'=>'पायरी २ पैकी २: %s कनेक्ट करा','Enter the address of your OpenAI-compatible service, ending in /v1. A key is only needed if the service asks for one.'=>'तुमच्या OpenAI-सुसंगत सेवेचा पत्ता प्रविष्ट करा, जो /v1 ने संपतो. सेवेने विचारल्याससच की (key) आवश्यक आहे.','Open %s and sign in (or create a free account).'=>'%s उघडा आणि साइन इन करा (किंवा मोफत खाते तयार करा).','the %s API keys page'=>'%s API कीज पृष्ठ','Create a new key and copy it.'=>'एक नवीन की तयार करा आणि ती कॉपी करा.','Paste it below and press "Save and test". We send one tiny request to check it works.'=>'हे खाली पेस्ट करा आणि "Save and test" वर क्लिक करा. ते कार्य करते की नाही हे तपासण्यासाठी आम्ही एक छोटी विनंती पाठवतो.','Most providers need a little credit on the account before a key works: %s.'=>'की काम करण्यासाठी बहुतेक प्रदात्यांना खात्यावर थोड्या क्रेडिटची आवश्यकता असते: %s.','add credit'=>'क्रेडिट जोडा','← Choose a different provider'=>'← वेगळा प्रदाता निवडा','Address'=>'पत्ता','Saved key ends in …%s — paste a new one to replace it'=>'जतन केलेल्या कीचा शेवट …%s ने होतो — ती बदलण्यासाठी नवीन की पेस्ट करा','Key (optional)'=>'की (पर्यायी)','API key'=>'API की','Save and test'=>'जतन करा आणि चाचणी घ्या','Providers'=>'प्रदाता','Provider'=>'प्रोव्हायडर','Status'=>'स्थिती','Key'=>'किल्ली','Get a key'=>'की मिळवा','Test'=>'चाचणी','Remove'=>'काढून टाका','Saved by a newer plugin version: update this plugin, or enter the key again.'=>'प्ललगिनाच्या नवीन आवृत्तीद्वारे सेव्ह केले गेले आहे: हे प्लगइन अपडेट करा किंवा की पुन्हा प्रविष्ट करा.','The saved key can no longer be opened (the site\'s security keys changed). Enter it again.'=>'जतन केलेली की आता उघडता येत नाही (साइटच्या सुरक्षा की बदलल्या आहेत). ती पुन्हा प्रविष्ट करा.','Not connected'=>'कनेक्ट केलेले नाही','Connected — last test passed %s'=>'जोडले गेले — शेवटची चाचणी %s उत्तीर्ण झाली','Last test failed: %s'=>'शेवटची चाचणी अयशस्वी झाली: %s','Connected — not tested yet'=>'जोडलेले आहे — अद्याप तपासले गेलेले नाही','Which model to use'=>'कोणते मॉडेल वापरावे','★ marks our recommendation for that task. The list includes every model your key can use, read live from the provider.'=>'★ त्या कामासाठी आमच्या शिफारशीचे प्रतीक आहे. या यादीमध्ये तुमच्या की द्वारे वापरले जाऊ शकणारे प्रत्येक मॉडेल समाविष्ट आहे, जे थेट प्रदात्याकडून वाचले जाते.','— Recommended for the provider —'=>'— प्रदात्यासाठी शिफारस केलेले —','Save models'=>'मॉडेल जतन करा','Refresh the model lists from the providers'=>'प्रदात्यांकडून मॉडेल सूची रीफ्रेश करा','Images'=>'प्रतिमा','Connect OpenAI or Google Gemini to make images.'=>'प्रतिमा तयार करण्यासाठी OpenAI किंवा Google Gemini कनेक्ट करा.','— The newest image model of the first connected provider —'=>'— पहिल्या कनेक्ट केलेल्या प्रदाताचे सर्वात नवीन इमेज मॉडेल —','Site search (embeddings)'=>'साइट शोध (एम्बेदिग्ज)','Connect Google Gemini, OpenAI, Mistral or OpenRouter to build a search index of your site.'=>'तुमच्या साइटचा शोध निर्देशांक तयार करण्यासाठी Google Gemini, OpenAI, Mistral किंवा OpenRouter कनेक्ट करा.','— The newest embedding model of the first connected provider —'=>'— पहिल्या कनेक्ट केलेल्या प्रदाताचे सर्वात नवीन एम्बेडिंग मॉडेल —','Changing this rebuilds the search index of every plugin that uses it.'=>'हे बदलल्याने ते वापरणाऱ्या प्रत्येक प्लगइनचा शोध निर्देशांक (सर्च इंडेक्स) पुनर्निर्मित होतो.','best quality'=>'सर्वोत्तम गुणवत्ता','lowest cost'=>'सर्वात कमी किंमत','fastest'=>'सर्वात जलद','Add a model yourself'=>'स्वयं एक मॉडेल जोडा','A model came out today? Paste its exact name to use it straight away.'=>'आज एक नवीन मॉडेल लॉन्च झाले आहे का? ते त्वरित वापरण्यासाठी त्याचे अचूक नाव पेस्ट करा.','Model name'=>'मॉडेलचे नाव','Add model'=>'मॉडेल जोडा','Recommended models list'=>'शिफारस केलेल्या मॉडेल्सची सूची','The recommended models list could not be verified, so no recommendations are shown. Reinstall the plugin, or turn on daily updates below.'=>'शिफारस केलेल्या मॉडेल्सची सूची सत्यापित केली जाऊ शकली नाही, त्यामुळे कोणतीही शिफारस दर्शवली जात नाही. प्लगइन पुन्हा स्थापित करा किंवा खाली दररोजची अपडेट्स सुरू करा.','The list in use was published on %s. Each plugin update brings a fresh one.'=>'वापरलेली यादी %s रोजी प्रकाशित केली गेली होती. प्रत्येक प्लगइन अपडेट नवीन यादी आणते.','Also check Zinn Digital® once a day for an updated list.'=>'अपडेट केलेल्या सूचीसाठी Zinn Digital® तर्फे दररोज एकदा नक्की तपासा.','Only a plain download request is sent: no key, no site address, nothing about your content. The list is signed, and a list that fails the signature check is ignored.'=>'फक्त एक साधी डाउनलोड विनंती पाठवली जाते: कोणतीही की नाही, साइटचा पत्ता नाही, तुमच्या सामग्रीबद्दल काहीही नाही. सूची स्वाक्षरी केलेली आहे, आणि स्वाक्षरी तपासणीत अयशस्वी ठरलेली सूची दुर्लक्षित केली जाते.','Last checked %1$s: %2$s.'=>'शेवटची तपासणी %1$s: %2$s.','Save, and check now if turned on'=>'जतन करा, आणि सुरू असल्यास आता तपासा','a newer list was installed'=>'एक नवीन सूची स्थापित केली गेली आहे','already up to date'=>'आधीपासूनच अद्ययावत','the download failed the signature check and was ignored'=>'डाउनलोडची स्वाक्षरी तपासणी अयशस्वी ठरली आणि ते दुर्लक्षित केले गेले','Zinn Digital® could not be reached; the current list stays in use'=>'Zinn Digital® शी संपर्क साधता आला नाही; सद्यस्थितीतील सूची वापरात राहील','turned off'=>'बंद केले','Open'=>'उघडा','Check their status page'=>'त्यांचे स्थिती पृष्ठ तपासा','Open your billing page'=>'तुमचे बिलिंग पृष्ठ उघडा','Open your API keys page'=>'तुमचे API की पेज उघडा','Open the AI settings'=>'एआय सेटिंग्ज उघडा','Sorry, you are not allowed to do that.'=>'क्षमस्व, तुम्हाला असे करण्याची परवानगी नाही.','Unknown provider.'=>'अज्ञात प्रोव्हायडर.','Enter the address of your service, for example http://localhost:11434/v1.'=>'तुमच्या सेवेचा पत्ता प्रविष्ट करा, उदाहरणार्थ http://localhost:11434/v1.','That does not look like an API key. Copy it again, without spaces.'=>'ती API की वाटत नाही. ती पुन्हा कॉपी करा, रिकाम्या जागांशिवाय.','Paste your API key first.'=>'पहिले तुमची API की पेस्ट करा.','Key removed.'=>'किल्ली काढली.','Models saved.'=>'मॉडेल जतन केले.','Enter the model\'s exact name, for example as the provider\'s documentation writes it.'=>'मॉडेलचे अचूक नाव प्रविष्ट करा, उदाहरणार्थ प्रदात्याच्या दस्तऐवजीकरणामध्ये (डॉक्युमेंटेशनमध्ये) लिहिल्याप्रमाणे.','Added %s. Choose it under "Which model to use".'=>'%s जोडले आहे. "कोणते मॉडेल वापरायचे" या अंतर्गत ते निवडा.','Model removed.'=>'मॉडेल काढले.','Daily updates are off. The list that came with the plugin is used.'=>'दैनिक अपडेट बंद आहेत. प्लगइनसोबत आलेली सूची वापरली जाते.','Checked: %s.'=>'तपासले आहे: %s.','Model lists refreshed.'=>'मॉडेल सूची रीफ्रेश केली.','Your AI key was saved by a newer version of one of your plugins. Update this plugin, or enter the key again in the AI settings.'=>'तुमची एआय की तुमच्या एका प्लगइनच्या नवीन आवृत्तीद्वारे सेव्ह केली गेली आहे. हे प्लगइन अपडेट करा किंवा एआय सेटिंग्जमध्ये की पुन्हा प्रविष्ट करा.','Your saved AI key can no longer be opened (the site\'s security keys changed). Enter it again in the AI settings.'=>'तुमची सेव्ह केलेली AI की आता उघडू शकत नाही (साइटच्या सुरक्षा की बदलल्या आहेत). AI सेटिंग्जमध्ये ती पुन्हा प्रविष्ट करा.','AI is not set up yet. Add a key for an AI provider in the AI settings.'=>'AI अद्याप कॉन्फिगर केलेले नाही. AI सेटिंग्जमध्ये AI प्रोव्हायडरसाठी एक की जोडा.','No model is chosen for this task. Pick one in the AI settings.'=>'या कार्यासाठी कोणतेही मॉडेल निवडलेले नाही. AI सेटिंग्जमध्ये एक निवडा.','That AI provider is not supported by this version of the plugin.'=>'प्लॅगइनच्या या आवृत्तीद्वारे त्या AI प्रदात्याचे समर्थन केले जात नाही.','No AI provider that can make images is connected. Add an OpenAI or Google Gemini key in the AI settings.'=>'प्रतिमा तयार करू शकणारा कोणताही AI प्रदाता कनेक्ट केलेला नाही. AI सेटिंग्जमध्ये OpenAI किंवा Google Gemini की जोडा.','This AI provider cannot make images. Choose OpenAI or Google Gemini for images in the AI settings.'=>'हा एआय (AI) प्रदाता प्रतिमा तयार करू शकत नाही. एआय (AI) सेटिंग्जमध्ये प्रतिमांसाठी OpenAI किंवा Google Gemini निवडा.','Your AI key cannot use any image model. Check the key\'s permissions with the provider, or choose another provider for images.'=>'तुमची AI की कोणतीही इमेज मॉडेल वापरू शकत नाही. प्रोव्हायडरकडे कीच्या परवानग्या तपासा किंवा इमेजसाठी दुसरा प्रोव्हायडर निवडा.','No connected AI provider can build a search index. Add a Google Gemini, OpenAI, Mistral or OpenRouter key in the AI settings.'=>'कोणताही जोडलेला AI प्रदाता शोध निर्देशांक तयार करू शकत नाही. AI सेटिंग्जमध्ये Google Gemini, OpenAI, Mistral किंवा OpenRouter की जोडा.','Your AI key cannot use any embedding model. Check the key\'s permissions with the provider, or choose another provider for site search.'=>'तुमची एआय की कोणतीही एम्बेडिंग मॉडेल वापरू शकत नाही. प्रदातासोबत कीच्या परवानगी तपासा किंवा साइट शोधासाठी दुसरा प्रदाता निवडा.','This AI provider cannot build a search index. Connect Google Gemini, OpenAI, Mistral or a compatible service for site search.'=>'हा AI प्रदाता शोध अनुक्रमणिका (search index) तयार करू शकत नाही. साइट शोधण्यासाठी Google Gemini, OpenAI, Mistral किंवा सुसंगत सेवा कनेक्ट करा.','This site could not reach your AI service. Check that it is running and that its address is reachable from your web server (a service on your own computer is not reachable from a hosted site).'=>'हे साइट तुमच्या AI सेवेपर्यंत पोहोचू शकली नाही. ती सुरू आहे आणि तिचा पत्ता तुमच्या वेब सर्व्हरवरून पोहोचण्यायोग्य आहे याची खात्री करा (तुमच्या स्वतःच्या संगणकावरील सेवा होस्ट केलेल्या साइटवरून पोहोचण्यायोग्य नसते).','This site could not reach %s. Check their status page; if they are up, your host may be blocking outgoing connections, or the address is wrong.'=>'हे साइट %s पर्यंत पोहोचू शकली नाही. त्यांच्या स्टेटस पेजची तपासणी करा; जर ती चालू असेल, तर तुमचा होस्ट आउटगोइंग कनेक्शन ब्लॉक करत असेल किंवा पत्ता चुकीचा असेल.','%s says your account has no credit or quota left. Add credit or raise your limit in your account with them, then try again.'=>'%s सांगते की तुमच्या खात्यात कोणतेही क्रेडिट किंवा कोटा शिल्लक नाही. त्यांच्याकडील तुमच्या खात्यात क्रेडिट जोडा किंवा तुमची मर्यादा वाढवा, नंतर पुन्हा प्रयत्न करा.','%s did not accept your key. It may be mistyped, revoked or expired. Create a new key and paste it here.'=>'%s ने आपकी कुंजी स्वीकार नहीं की। यह गलत टाइप की गई, निरस्त की गई या समाप्त हो चुकी हो सकती है। एक नई कुंजी बनाएं और उसे यहाँ पेस्ट करें।','%s refused this request for your key. The key may not have access to this model or feature, or your account needs verifying.'=>'%s ने तुमच्या कीसाठी ही विनंती नाकारली आहे. की ला या मॉडेल किंवा वैशिष्ट्यात प्रवेश नसू शकतो किंवा तुमच्या खात्याची पडताळणी होणे आवश्यक आहे.','The model "%1$s" is not available from %2$s for your key. Choose another model in the AI settings.'=>'तुमच्या कीसाठी %2$s कडून "%1$s" हे मॉडेल उपलब्ध नाही. AI सेटिंग्जमध्ये दुसरे मॉडेल निवडा.','Your %2$s plan does not include the model "%1$s". Choose another model in the AI settings, or upgrade your plan with them.'=>'तुमच्या %2$s प्लॅनमध्ये "%1$s" हे मॉडेल समाविष्ट नाही. AI सेटिंग्जमध्ये दुसरे मॉडेल निवडा किंवा त्यांच्यासह तुमचे प्लॅन अपग्रेड करा.','%s is limiting how fast your key can send requests. Wait a minute and try again, or raise your rate limit with them.'=>'%s तुमच्या की द्वारे विनंत्या पाठवण्याचा वेग मर्यादित करत आहे. एक मिनिट थांबा आणि पुन्हा प्रयत्न करा, किंवा त्यांच्याकडे तुमची दर मर्यादा वाढवा.','%s is having problems right now (an outage or overload on their side). Nothing is wrong with your settings. Try again shortly.'=>'%s ला सध्या समस्या येत आहेत (त्यांच्या बाजूने सेवा खंडित झाली आहे किंवा जास्त भार पडला आहे). तुमच्या सेटिंग्जमध्ये कोणतीही अडचण नाही. थोड्या वेळाने पुन्हा प्रयत्न करा.','The AI request failed for a reason we could not identify. Try again; if it keeps happening, contact support with the details below.'=>'AI विनंती ओळख न शकलेल्या कारणास्तव अयशस्वी झाली. पुन्हा प्रयत्न करा; जर समस्या कायम राहिल्यास, खालील तपशीलांसह सपोर्टशी संपर्क साधा.','The AI provider answered in a form this plugin could not read. Try again; if it keeps happening, choose another model or contact support.'=>'AI प्रदात्याने अशा स्वरूपात उत्तर दिले जे हे प्लगइन वाचू शकले नाही. पुन्हा प्रयत्न करा; जर हे सतत घडत राहिले, तर दुसरे मॉडेल निवडा किंवा समर्थनाशी (सपोर्टशी) संपर्क साधा.','Custom (OpenAI-compatible)'=>'कस्टम (OpenAI-संगत)','Save a key for this provider first.'=>'आधी या प्रोफायडरसाठी एक की सेव्ह करा.','Your key works, but the provider lists no text model for it. Add a model yourself below.'=>'तुमची की काम करते, परंतु प्रदात्याने यासाठी कोणतीही टेक्स्ट मॉडेल सुचवली नाही. खाली स्वतः एक मॉडेल जोडा.','Connected. %1$s answered using %2$s. Your AI features are ready to use.'=>'कनेक्ट केले आहे. %1$s ने %2$s वापरून उत्तर दिले. तुमची AI वैशिष्ट्ये वापरण्यासाठी तयार आहेत.','Your user role is not allowed to use AI on this site. Ask an administrator.'=>'तुमच्या युजर भूमिकेला या साइटवर AI वापरण्याची परवानगी नाही. प्रशासकाशी संपर्क साधा.','This site has reached its monthly AI spending limit. An administrator can raise it in the AI settings.'=>'या साइटने त्यांची मासिक AI खर्चाची मर्यादा गाठली आहे. एखादा प्रशासक AI सेटिंग्जमध्ये ती वाढवू शकतो.','This site has reached its monthly limit of AI requests. An administrator can raise it in the AI settings.'=>'या साइटने AI विनंत्यांची मासिक मर्यादा ओरंडली आहे. प्रशासक AI सेटिंग्जमध्ये ती वाढवू शकतात.','Usage and cost'=>'वापर आणि खर्च','The log, limits and role permissions apply to AI used through: %s.'=>'लॉग, मर्यादा आणि भूमिका परवानग्या %s द्वारे वापरल्या जाणाऱ्या AI ला लागू होतात.','Costs are approximate, worked out from published prices; a model with no known price counts as zero.'=>'खर्च अंदाजे आहेत, प्रकाशित किमतींवरून काढले आहेत; कोणतीही ज्ञात किंमत नसलेले मॉडेल शून्य मोजले जाते.','This month: %1$s requests, about %2$s.'=>'या महिन्यात: %1$s विनंत्या, सुमारे %2$s.','When'=>'जेव्हा','Who'=>'कोण','Used for'=>'यासाठी वापरले जाते','Model'=>'मॉडेल','Tokens in / out'=>'इन / आउट टोकन्स','About'=>'विषयी','Result'=>'निकाल','No AI requests have been made yet.'=>'अद्याप कोणतीही AI विनंती केली गेलेली नाही.','Done'=>'पूर्ण झाले','Limits and permissions'=>'मर्यादा आणि परवानग्या','Monthly spending limit (US dollars)'=>'मासिक खर्च मर्यादा (US डॉलर्स)','Leave empty for no limit. AI stops for the rest of the month once the approximate cost reaches it.'=>'कोणतीही मर्यादा न ठेवण्यासाठी रिकामी सोडा. अंदाजे खर्च त्यावर पोहोचल्यानंतर AI महिनाभर थांबते.','Monthly request limit'=>'मासिक विनंती मर्यादा','Leave empty for no limit.'=>'कोणतीही मर्यादा न ठेवण्यासाठी रिकामे सोडा.','Who may use AI'=>'एआय कोण वापरू शकेल','Tick none to let everyone who can use the plugin\'s features use AI. Administrators can always use it.'=>'प्लॅगइनची वैशिष्ट्ये वापरू शकणाऱ्या सर्वांना एआय (AI) वापरण्याची मुभा देण्यासाठी काहीही निवडू नका. प्रशासक नेहमीच ते वापरू शकतात.','Save limits and permissions'=>'मर्यादा आणि परवानग्या जतन करा','Limits and permissions saved.'=>'मर्यादा आणि परवानग्या जतन केल्या.','Content'=>'आंतरिक आशय','Not found.'=>'आढळले नाही.','%s joined the chat.'=>'%s चॅटमध्ये सामील झाले आहेत.','Type a reply first.'=>'आधी उत्तर टाइप करा.','The chat has ended. Thank you for contacting us.'=>'चर्चा संपली आहे. आमच्याशी संपर्क साधल्याबद्दल धन्यवाद.','You are chatting with the assistant again.'=>'तुम्ही पुन्हा सहाय्यकाशी गप्पा मारत आहात.','This conversation is now ticket #%d. We will reply by email.'=>'हा संवाद आता तिकीट #%d झाला आहे. आम्ही ईमेलद्वारे उत्तर देऊ.','Type a question first.'=>'पहिले प्रश्न टाईप करा.','The whole site is being read again in the background.'=>'संपूर्ण साइट पार्श्वभूमीत पुन्हा वाचली जात आहे.','Meanings are being rebuilt in the background.'=>'पार्श्वभूमीवर अर्थ पुन्हा तयार केले जात आहेत.','Submit a ticket form'=>'तिकीट फॉर्म सबमिट करा','Heading'=>'शीर्षक','Default subject'=>'डिसेंबर विषय','Button text'=>'बटण मजकूर','Show the subject field (yes or no)'=>'विषय क्षेत्र दाखवा (हो किंवा नाही)','My support requests'=>'माझ्या समर्थन विनंत्या','Chat button'=>'गप्पा बटण','Chat with us'=>'आमच्याशी गप्पा मारा','Support'=>'सपोर्ट','Thank you. Your request is ticket #%d. We have emailed you a link to follow it.'=>'धन्यवाद. तुमची विनंती तिकीट क्र. #%d आहे. त्याचा पाठपुरावा करण्यासाठी आम्ही तुम्हाला ईमेलद्वारे एक लिंक पाठवली आहे.','Your reply has been sent.'=>'तुमचे उत्तर पाठवले गेले आहे.','If there is a request under that address, we have emailed you a new link.'=>'जर त्या पत्त्यावर कोणतीही विनंती असेल, तर आम्ही तुम्हाला एक नवीन दुवा ईमेल केला आहे.','Something went wrong. Please check the form and try again.'=>'काहीतरी चूक झाली आहे. कृपया फॉर्म तपासा आणि पुन्हा प्रयत्न करा.','Your message could not be sent.'=>'तुमचा संदेश पाठवता आला नाही.','You are sending messages too quickly. Please wait a little and try again.'=>'तुम्ही खूप जलद संदेश पाठवत आहात. कृपया थोडा वेळ थांबा आणि पुन्हा प्रयत्न करा.','Please agree to the privacy notice to send your request.'=>'तुमची विनंती पाठवण्यासाठी कृपया गोपनीयता सूचना स्वीकारा.','Please complete the check to show you are not a robot.'=>'तुम्ही रोबोट नाही आहात हे दाखवण्यासाठी कृपया तपासणी पूर्ण करा.','Sign in to see your support requests.'=>'तुमच्या सपोर्ट विनंत्या पाहण्यासाठी साइन इन करा.','Your name'=>'तुमचे नाव','Your email'=>'तुमचा ईमेल','Subject'=>'विषय','Which order is this about?'=>'ही ऑर्डर कशाबद्दल आहे?','Not about an order'=>'ऑर्डरबद्दल नाही','How can we help?'=>'आम्ही कशी मदत करू शकतो?','Privacy policy'=>'गोपनीयता धोरण','Send request'=>'विनंती पाठवा','All requests'=>'सर्व विनंत्या','Your support requests'=>'तुमच्या समर्थन विनंत्या','You have no support requests yet.'=>'तुमची अद्याप कोणतीही सपोर्ट विनंती नाही.','Updated'=>'अपडेट केलेले','New request'=>'नवीन विनंती','This link has expired. Enter your email address and we will send you a new one.'=>'ही लिंक कालबाह्य झाली आहे. तुमचा ईमेल पत्ता प्रविष्ट करा आणि आम्ही तुम्हाला नवीन पाठवू.','This link is not valid. Enter your email address and we will send you a link to your requests.'=>'हा दुवा वैध नाही. तुमचा ईमेल पत्ता प्रविष्ट करा आणि आम्ही तुम्हाला तुमच्या विनंत्यांचा दुवा पाठवू.','Email me a new link'=>'मला नवीन लिंक ईमेल करा','Request #%1$d: %2$s'=>'विनंती #%1$d: %2$s','Status:'=>'स्थिती:','Your reply'=>'तुमचे उत्तर','Send reply'=>'उत्तर पाठवा','You'=>'तुम्ही','Submit a ticket'=>'तिकीट सबमिट करा','Add to Menu'=>'मेन्यूमध्ये जोडा','Create the support page on the Zinn® Chat setup screen to add a "Submit a ticket" link.'=>'Zinn® Chat सेटअप स्क्रीनवर "टिकट सबमिट करा" दुवा जोडण्यासाठी सपोर्ट पेज तयार करा.','[#%1$d] We have your request: %2$s'=>'[#%1$d] आम्हाला तुमची विनंती प्राप्त झाली आहे: %2$s','Thank you for contacting us. We have received your request and will reply as soon as we can.'=>'आमशी संपर्क साधल्याबद्दल धन्यवाद. आम्हाला आपकी विनंती प्राप्त झाली आहे आणि आम्ही शक्य तितक्या लवकर उत्तर देऊ.','View your request'=>'तुमची विनंती पहा','[#%1$d] New ticket: %2$s'=>'[#%1$d] नवीन तिकीट: %2$s','Open the ticket'=>'तिकीट उघडा','[#%1$d] New reply: %2$s'=>'[#%1$d] नवीन उत्तर: %2$s','You can reply on the page below.'=>'तुम्ही खालील पृष्ठावर उत्तर देऊ शकता.','View and reply'=>'पहा आणि उत्तर द्या','[#%1$d] Customer replied: %2$s'=>'[#%1$d] ग्राहकाने उत्तर दिले: %2$s','A visitor is waiting in chat #%d'=>'चॅट #%d मध्ये एक व्हिजिटर वाट पाहत आहे','A visitor asked to talk to a person and is waiting for an answer.'=>'एका अभ्यागतने व्यक्तीशी बोलण्याची विनंती केली आहे आणि तो उत्तराची प्रतीक्षा करत आहे.','Answer now'=>'आता उत्तर द्या','Your chat with %s'=>'%s सोबत तुमचे चॅट','[#%d] Your link to your request'=>'[#%d] तुमच्या विनंतीची लिंक','Here is a new link to your request. The old one no longer works.'=>'तुमच्या विनंतीसाठी येथे एक नवीन दुवा आहे. जुनी लिंक आता काम करत नाही.','From: %s'=>'येथून: %s','a visitor'=>'एक भेट देणारा व्यक्ती','Zinn® Chat chats and support tickets'=>'Zinn® Chat चे चॅट्स आणि सपोर्ट तिकिटे','Chats'=>'चॅट्स','Started'=>'सुरू झाले','Name'=>'नाव','Email'=>'ईमेल','Page'=>'पृष्ठ','Messages'=>'संदेश','Support tickets'=>'सपोर्ट तिकीटं','Ticket'=>'तिकीट','Opened'=>'उघडले','When you use the chat or submit a support request, we store your messages, the name and email address you give us, the page you were on and a coded form of your IP address, so that we can answer you and keep a record of your request.'=>'जेव्हा तुम्ही चॅट वापरता किंवा समर्थन विनंती सबमिट करता, तेव्हा आम्ही तुमचे संदेश, तुम्ही आम्हाला दिलेले नाव आणि ईमेल पत्ता, तुम्ही ज्या पेजवर होतात ते पेज आणि तुमच्या IP पत्त्याचे कोड केलेले रूप संग्रहित करतो, जेणेकरून आम्ही तुम्हाला 